"""Generate review-only PostgreSQL DDL from the exact application metadata. Never connect."""

from pathlib import Path

from sqlalchemy.dialects.postgresql import dialect
from sqlalchemy.schema import CreateIndex, CreateTable

from rp1_monitor import central_tables, report_store  # noqa: F401
from rp1_monitor.storage import metadata

ROOT = Path(__file__).resolve().parents[1]


def schema_sql():
    statements = [
        "-- REVIEW ONLY. Fresh dedicated database; no automatic deployment or data deletion.",
        "-- Generated by scripts/generate_postgres_design.py; application metadata is authoritative.",
        "BEGIN;",
        "SET LOCAL lock_timeout = '5s';",
        "CREATE SCHEMA rp1_monitor;",
        "REVOKE ALL ON SCHEMA rp1_monitor FROM PUBLIC;",
        "SET LOCAL search_path = rp1_monitor, pg_catalog;",
    ]
    pg = dialect()
    for table in metadata.sorted_tables:
        statements.append(str(CreateTable(table).compile(dialect=pg)).strip() + ";")
        statements.extend(
            str(CreateIndex(index).compile(dialect=pg)).strip() + ";"
            for index in sorted(table.indexes, key=lambda index: index.name)
        )
    statements.append("COMMIT;")
    return "\n\n".join(statements) + "\n"


if __name__ == "__main__":
    target = ROOT / "deploy/postgres/001_schema.review.sql"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(schema_sql())
    print(f"Generated review-only DDL: {target}")
